/**
 * Where an asset's bytes live.
 *
 * Split out of `store.js` so the trash can compute the same paths without importing
 * the store — the store imports the trash, and a cycle between them would mean one of
 * the two silently seeing a half-built module.
 */
import { join } from 'node:path'
import { characterDir } from './config.js'

/** Asset ids are generated by the store; anything else is a request and is rejected. */
const SAFE_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/

/**
 * @param {{name?:string, id?:string}} character
 * @param {{id:string, kind:string, ext:string}} asset
 * @returns {string} absolute path
 */
export function assetFilePath(character, asset) {
  if (!SAFE_ID.test(String(asset?.id ?? ''))) {
    throw new Error(`不安全的资源 id "${asset?.id}"`)
  }
  const ext = String(asset?.ext ?? 'png').replace(/[^a-z0-9]/gi, '') || 'png'
  const bucket = asset.kind === 'photo' ? 'photos' : 'views'
  return join(characterDir(character?.name ?? character?.id), bucket, `${asset.id}.${ext}`)
}

/** The folder a character's uploads live in — the one the trash borrows a name from. */
export function photoDir(character) {
  return join(characterDir(character?.name ?? character?.id), 'photos')
}

export default { assetFilePath, photoDir, SAFE_ID }
